BEGIN;

-- 1. Harden log_price_change trigger function to handle non-session migrations safely
CREATE OR REPLACE FUNCTION public.log_price_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
BEGIN
    IF (OLD.price IS DISTINCT FROM NEW.price) OR
       (OLD.mrp IS DISTINCT FROM NEW.mrp) OR
       (OLD.cost IS DISTINCT FROM NEW.cost) THEN
        INSERT INTO price_audit_log (
            item_id,
            store_id,
            old_price,
            new_price,
            old_mrp,
            new_mrp,
            old_cost,
            new_cost,
            changed_by,
            source
        ) VALUES (
            NEW.id,
            COALESCE(public.get_current_user_store_id(), '4acf0fb2-f831-4205-b9f8-e1e8b4e6e8fd'::uuid),
            OLD.price,
            NEW.price,
            OLD.mrp,
            NEW.mrp,
            OLD.cost,
            NEW.cost,
            auth.uid(),
            'reconciliation_migration'
        );
    END IF;
    RETURN NEW;
END;
$function$;

-- 2. Purge synthetic test items if present
